  }

  // clear memory vector indexers
  memory_vector_indexers_.clear();
  quant_memory_vector_indexers_.clear();
  memory_vector_block_ids_.clear();
  quant_memory_vector_block_ids_.clear();

  fresh_persist_block_offset();
  return Status::OK();
